<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="k-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="k-opbar"><button @click="emit('back')">←</button><strong>Kurly</strong><div><button data-testid="shopping-open-service" @click="emit('open-service')"><i class="fas fa-circle-question"></i></button><button @click="emit('open-orders')"><i class="fas fa-clock-rotate-left"></i></button><button @click="emit('open-cart')"><i class="fas fa-basket-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="k-basket"><header><p>DAWN BASKET / TEMPERATURE CHECK</p><h1>{{ l('清晨之前，先把温层分清','Sort every temperature lane before dawn') }}</h1><div><span><i class="fas fa-snowflake"></i> CHILLED <b>{{ cartItems.filter(x=>x.product.category==='grocery').length }}</b></span><span><i class="fas fa-box"></i> AMBIENT <b>{{ cartItems.filter(x=>x.product.category!=='grocery').length }}</b></span></div></header><div v-if="!cartItems.length" class="k-empty">{{ l('温层购物篮为空','Temperature basket is empty') }}</div><div v-else class="k-basket-layout"><section><article v-for="line in cartItems" :key="line.productId"><span class="k-food"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>{{ line.product.category==='grocery'?'CHILLED':'AMBIENT' }}</em></span><div><small>DAWN DELIVERY ITEM</small><strong>{{ productDisplayTitle(line.product) }}</strong><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><p>DAWN REVIEW</p><strong>{{ cartTotalLabel }}</strong><dl><div><dt>{{ l('保冷分袋','Cold bags') }}</dt><dd>{{ Math.max(1,Math.ceil(cartQuantity/3)) }}</dd></div><div><dt>{{ l('预计到达','Arrival') }}</dt><dd>{{ l('结算时确认','At review') }}</dd></div></dl><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" />{{ l('晨间礼物','Dawn gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">{{ l('手动收件人','Manual recipient') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">{{ l('确认清晨配送','Confirm dawn order') }}</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="k-deliveries"><header><div><p>DAWN DELIVERIES</p><h1>{{ l('清晨订单','Morning deliveries') }}</h1></div><button @click="emit('open-logistics')">COLD CHAIN →</button></header><article v-for="order in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="k-moon"><i class="fas fa-moon"></i><span>07:00</span></div><div><small>{{ formatLogisticsDate(order.createdAt) }}</small><h2>{{ order.items.map(x=>x.title).join(' / ') }}</h2><p>{{ order.itemCount }} ITEMS · {{ formatOrderTotal(order) }}</p><b>{{ orderStatusLabel(order.status) }}</b></div><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">OPEN</button><button @click="emit('delete-order',order.id)">×</button></article><div v-if="!orders.length" class="k-empty">NO DAWN DELIVERIES</div></section>
    <section v-else-if="pageKey==='logistics'" class="k-chain" data-testid="shopping-logistics-panel"><header><button @click="emit('open-orders')">← DELIVERIES</button><p>COLD CHAIN</p><h1>{{ l('从拣货到清晨门口','From picking to the morning doorstep') }}</h1></header><article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="k-temp-line"><span>2–8°C</span><i></i><b>{{ row.latestEvent?logisticsEventTypeLabel(row.latestEvent.type):'PICKING' }}</b></div><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><em :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</em><small v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ row.latestEvent.trackingCode||row.latestEvent.locationHint }}</small><button :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">VIEW DELIVERY</button></article><div v-if="!logisticsRows.length" class="k-empty">NO COLD-CHAIN RECORDS</div></section>
    <section v-else-if="selectedOrder" class="k-detail" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><p>DAWN DELIVERY DETAIL</p><h1>{{ formatLogisticsDate(selectedOrder.createdAt) }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="k-detail-hero"><i class="fas fa-moon"></i><div><span>ARRIVAL WINDOW</span><strong>BEFORE 07:00 / CONFIRMED IN ORDER</strong></div><b data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</b></section><section class="k-detail-items"><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>{{ item.productId?.includes('grocery')?'CHILLED':'PACKED' }}</span><h2>{{ item.title }}</h2><p>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item,quantity:1 }) }}</p><strong>{{ formatOrderItemSubtotal(item) }}</strong></article></section><section class="k-detail-timeline" data-testid="shopping-order-detail-timeline"><h2>COLD CHAIN NOTES</h2><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><i class="fas fa-snowflake"></i><div><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary||event.title }}</p><span>{{ formatLogisticsDate(event.createdAt) }}</span></div></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO RECORDED COLD-CHAIN EVENTS</p></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COMPLETE</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE</button></footer></section>
  </main>
</template>
